    /// <summary>Authored default copy. Entries are copied into an editable localization SO, preserving existing edits.</summary>
    public static class DefaultLocalizationBuilder
    {
        public const string AssetPath = "Assets/_LifeLine/Data/Localization/DefaultLocalization.asset";

        [MenuItem("LifeLine/Localization/Create or Extend Default Table")]
        public static void BuildDefaultTable() { Selection.activeObject = Build(); }

        public static LocalizationTable Build(bool overwriteExisting = false)
        {
            EnsureFolder("Assets/_LifeLine/Data/Localization");
            LocalizationTable table = AssetDatabase.LoadAssetAtPath<LocalizationTable>(AssetPath);
            bool created = table == null;
            if (created) { table = ScriptableObject.CreateInstance<LocalizationTable>(); AssetDatabase.CreateAsset(table, AssetPath); }
            List<LocalizationTable.Entry> defaults = CreateDefaultEntries();
            bool changed = created || overwriteExisting || table.entries == null;
            if (overwriteExisting || table.entries == null) table.entries = new List<LocalizationTable.Entry>();
            var keys = new HashSet<string>();
            foreach (LocalizationTable.Entry existing in table.entries) if (existing != null && !string.IsNullOrEmpty(existing.key)) keys.Add(existing.key);
            foreach (LocalizationTable.Entry entry in defaults) if (keys.Add(entry.key)) { table.entries.Add(entry); changed = true; }
            if (changed) { table.NotifyChanged(); EditorUtility.SetDirty(table); AssetDatabase.SaveAssetIfDirty(table); }
            return table;
        }

        static void EnsureFolder(string folder)
        {
            string[] parts = folder.Split('/'); string current = parts[0];
            for (int i = 1; i < parts.Length; i++)
            {
                string next = current + "/" + parts[i];
                if (!AssetDatabase.IsValidFolder(next)) AssetDatabase.CreateFolder(current, parts[i]);
                current = next;
            }
        }

